body.script:
var $=function(i){return document.getElementById(i)};
var L={ar:['العربية','ar-SA','ara'],en:['الإنجليزية','en-US','eng'],ur:['الأردية','ur-PK','urd'],hi:['الهندية','hi-IN','hin'],bn:['البنغالية','bn-BD','ben'],id:['الإندونيسية','id-ID','ind'],tl:['الفلبينية','fil-PH','fil'],fa:['الفارسية','fa-IR','fas'],tr:['التركية','tr-TR','tur'],fr:['الفرنسية','fr-FR','fra'],es:['الإسبانية','es-ES','spa'],de:['الألمانية','de-DE','deu'],ru:['الروسية','ru-RU','rus'],zh:['الصينية','zh-CN','chi_sim'],ko:['الكورية','ko-KR','kor'],ja:['اليابانية','ja-JP','jpn'],it:['الإيطالية','it-IT','ita']};
function fill(id,def){var s=$(id),h='';for(var k in L)h+=''+L[k][0]+'';s.innerHTML=h}
fill('sl','en');fill('tl','ar');fill('ol','en');fill('ot','ar');fill('cs','en');fill('ct','ar');

// theme
if(localStorage.getItem('dark')=='1'){document.body.classList.add('dark');$('theme').textContent='☀️'}
$('theme').onclick=function(){var d=document.body.classList.toggle('dark');localStorage.setItem('dark',d?'1':'0');this.textContent=d?'☀️':'🌙'};

// tabs
document.querySelectorAll('.tabs button').forEach(function(b){b.onclick=function(){
document.querySelectorAll('.tabs button,.tab').forEach(function(e){e.classList.remove('on')});
b.classList.add('on');$(b.dataset.t).classList.add('on')}});

// translate
function tr(t,s,d){
var u='https://translate.googleapis.com/translate_a/single?client=gtx&sl='+s+'&tl='+d+'&dt=t&q='+encodeURIComponent(t);
return fetch(u).then(function(r){return r.json()}).then(function(j){var o='';j[0].forEach(function(p){if(p&&p[0])o+=p[0]});if(!o)throw 0;return o})
.catch(function(){return fetch('https://api.mymemory.translated.net/get?q='+encodeURIComponent(t.slice(0,450))+'&langpair='+s+'|'+d).then(function(r){return r.json()}).then(function(j){return j.responseData.translatedText})})}
$('go').onclick=function(){var t=$('src').value.trim();if(!t){$('st').textContent='الرجاء كتابة نص';return}
$('st').textContent='⏳ جاري الترجمة...';
tr(t,$('sl').value,$('tl').value).then(function(r){$('tgt').value=r;$('st').textContent='✅ تمت الترجمة'}).catch(function(){$('st').textContent='❌ تعذرت الترجمة'})};
function swap(){var a=$('sl').value;$('sl').value=$('tl').value;$('tl').value=a;var t=$('src').value;$('src').value=$('tgt').value;$('tgt').value=t}
function cl(){$('src').value='';$('tgt').value=''}
function copy(id){navigator.clipboard&&navigator.clipboard.writeText($(id).value);$('st').textContent='✅ تم النسخ'}

// speech
function say(t,l){if(!window.speechSynthesis||!t)return;var u=new SpeechSynthesisUtterance(t);u.lang=L[l][1];speechSynthesis.cancel();speechSynthesis.speak(u)}
function speak(i,l){say($(i).value,$(l).value)}
var rec=null,SR=window.SpeechRecognition||window.webkitSpeechRecognition;
function mic(){if(!SR){alert('المتصفح لا يدعم الإدخال الصوتي');return}
rec=new SR();rec.lang=L[$('sl').value][1];$('micb').textContent='⏹';
rec.onresult=function(e){$('src').value+=(($('src').value?' ':'')+e.results[0][0].transcript)};
rec.onend=function(){$('micb').textContent='🎤'};rec.start()}

// OCR
$('file').onchange=function(){var f=this.files[0];if(f){$('pv').src=URL.createObjectURL(f);$('pv').style.display='block'}};
$('ocr').onclick=function(){var f=$('file').files[0];if(!f){$('ost').textContent='اختر صورة أولا';return}
$('ost').textContent='⏳ جاري استخراج النص...';
Tesseract.recognize(f,L[$('ol').value][2],{logger:function(m){if(m.status=='recognizing text')$('ost').textContent='⏳ '+Math.round(m.progress*100)+'%'}})
.then(function(r){var t=r.data.text.trim();if(!t){$('ost').textContent='⚠️ لم يُعثر على نص';return}
$('oext').value=t;$('ost').textContent='⏳ جاري الترجمة...';
return tr(t,$('ol').value,$('ot').value).then(function(x){$('otr').value=x;$('ost').textContent='✅ تم'})})
.catch(function(){$('ost').textContent='❌ حدث خطأ'})};

// flashcards
var cards=[];try{cards=JSON.parse(localStorage.getItem('cards')||'[]')}catch(e){}
var ci=0;
function save(){localStorage.setItem('cards',JSON.stringify(cards))}
function esc(s){return String(s).replace(/[&<>"]/g,function(c){return{'&':'&','<':'<','>':'>','"':'"'}[c]})}
function show(){$('card').classList.remove('f');
if(!cards.length){$('cf').textContent='أضف كلمة لتبدأ';$('cb').textContent='';$('cc').textContent='0 / 0';$('list').innerHTML='';return}
var c=cards[ci];$('cf').textContent=c.s;$('cb').textContent=c.t;$('cc').textContent=(ci+1)+' / '+cards.length;
$('list').innerHTML=cards.map(function(c){return'
'+esc(c.s)+' = '+esc(c.t)+''}).join('')}
$('card').onclick=function(){this.classList.toggle('f')};
function nav(d){if(cards.length){ci=(ci+d+cards.length)%cards.length;show()}}
function spk(){if(!cards.length)return;var c=cards[ci],f=$('card').classList.contains('f');say(f?c.t:c.s,f?c.tl:c.sl)}
function del(){if(!cards.length)return;cards.splice(ci,1);ci=0;save();show()}
$('add').onclick=function(){var w=$('w').value.trim(),s=$('cs').value,d=$('ct').value;if(!w||s==d)return;
var b=this;b.disabled=true;
tr(w,s,d).then(function(r){cards.push({s:w,t:r,sl:s,tl:d});save();ci=cards.length-1;$('w').value='';show()})
.catch(function(){alert('فشلت الترجمة')}).then(function(){b.disabled=false})};

// quiz
var qs=[],qi=0,sc=0;
function shuf(a){return a.slice().sort(function(){return Math.random()-.5})}
$('qz').onclick=function(){if(cards.length<2){alert('أضف بطاقتين على الأقل');return}
qs=shuf(cards).slice(0,10);qi=0;sc=0;$('quiz').style.display='block';nq()};
function nq(){var q=$('quiz');
if(qi>=qs.length){var p=Math.round(sc/qs.length*100);q.innerHTML='
🎉 نتيجتك: '+p+'%
'+sc+' من '+qs.length+'';return}
var c=qs[qi],o=shuf([c.t].concat(shuf(cards.filter(function(x){return x.t!=c.t}).map(function(x){return x.t})).slice(0,3))),h='
سؤال '+(qi+1)+' / '+qs.length+'
'+esc(c.s)+'';
o.forEach(function(x,i){h+=''+esc(x)+''});
q.innerHTML=h;
q.querySelectorAll('.opt').forEach(function(b){b.onclick=function(){
var ok=o[b.dataset.i]==c.t;if(ok)sc++;
q.querySelectorAll('.opt').forEach(function(x){x.disabled=true;if(o[x.dataset.i]==c.t)x.classList.add('ok')});
if(!ok)b.classList.add('no');setTimeout(function(){qi++;nq()},1200)}})}
show();
